// Generated by `warden ui record` from the recording "sign in". Review any FIXME before committing.
import { expect, test } from "../../index";
import { signIn } from "./helper-module";

const ids = {
	signInSubmit: "sign-in-submit",
	email: "email",
	password: "password",
	notes: "notes",
	list: "list",
	map: "map",
	todosScreen: "todos-screen",
	spinner: "spinner",
	rememberMe: "remember-me",
	banner: "banner",
	welcomeTitle: "welcome-title",
} as const;

test("sign in", async (fixtures) => {
	const { app, device, screen } = fixtures;
	const passwordSecret = process.env.WARDEN_UI_SECRET_PASSWORD;
	if (passwordSecret === undefined) throw new Error("set WARDEN_UI_SECRET_PASSWORD to run this spec");
	await app.open({ url: "warden-example://home", args: ["--demo"], wait: "quiet" });
	// link from outside the app
	await device.openLink("https://example.com/invite");
	await screen.getByTestId(ids.signInSubmit).tap();
	await device.settle();
	await screen.getByTestId(ids.email).fill("chris@example.com");
	await screen.getByTestId(ids.password).fill(passwordSecret);
	await screen.getByTestId(ids.notes).type("hello");
	await screen.getByTestId(ids.notes).press("Enter");
	await screen.getByTestId(ids.notes).press("Tab", { modifiers: ["shift"] });
	await screen.getByRole("button", "Row").longPress({ durationMs: 800 });
	await screen.getByTestId(ids.list).swipe({ direction: "down", momentum: "fast" });
	await screen.gesture.swipe({ direction: "left" });
	await screen.gesture.swipe({ from: { x: 200, y: 600 }, to: { x: 200, y: 200 }, durationMs: 400 });
	await screen.getByTestId(ids.map).pinch(2, { durationMs: 700 });
	await screen.gesture.pinch({ scale: 0.5 });
	// FIXME: pinch target was recorded by coordinates (recorded by coordinates)
	await screen.gesture.pinch({ scale: 3, center: { x: 150, y: 250 }, radius: 80 });
	await screen.getByTestId(ids.map).rotate(45);
	await screen.gesture.rotate({ degrees: -90, durationMs: 800, radius: 120 });
	await screen.gesture.path({
		paths: [
			[
				{ x: 100, y: 400 },
				{ x: 200, y: 300 },
				{ x: 300, y: 400 },
			],
		],
	});
	await screen.gesture.path({
		paths: [
			[
				{ x: 100, y: 400 },
				{ x: 150, y: 400 },
			],
			[
				{ x: 300, y: 400 },
				{ x: 250, y: 400 },
			],
		],
		durationMs: 450,
	});
	await screen.scrollUntilVisible(screen.getByRole("text", "Footer"), {
		direction: "down",
		maxSwipes: 5,
		timeout: 20000,
	});
	await screen.swipe({ direction: "up" });
	await expect(screen.getByTestId(ids.todosScreen)).toBeVisible({ timeout: 5000 });
	await expect(screen.getByTestId(ids.spinner)).toBeHidden();
	await screen.getByText("Done").waitFor({ state: "attached" });
	await screen.getByText("Gone").waitFor({ state: "detached", timeout: 1000 });
	await expect(screen.getByTestId(ids.rememberMe)).toBeChecked();
	await expect(screen.getByTestId(ids.rememberMe)).toBeChecked({ checked: false });
	await expect(screen.getByTestId(ids.signInSubmit)).not.toBeEnabled();
	await expect(screen.getByTestId(ids.signInSubmit)).toBeDisabled();
	await expect(screen.getByTestId(ids.banner)).toBeVisible();
	await expect(screen.getByTestId(ids.banner)).toBeHidden();
	await expect(screen.getByTestId(ids.welcomeTitle)).toHaveText("Welcome back");
	await expect(screen.getByTestId(ids.email)).toHaveValue("chris@example.com");
	await device.alert("accept");
	await device.alert("dismiss");
	await device.alert({ button: "Allow While Using App" });

	// Leave the app and come back
	await device.home();
	await device.back();
	if (!device.devtools) throw new Error("reload needs a Metro devtools session");
	await device.devtools.reloadJs();
	await signIn(fixtures);
	await device.orientation("landscapeLeft");
	await device.appearance("dark");
	await device.snapshot({ interactiveOnly: true });
	await device.screenshot("after-login");
	await device.screenshot("step-45");
	await screen.getByRole("switch").nth(1).tap();
	await screen.getByLabel("Settings").tap();
	await screen.getByRole("tab", "Profile").tap();
	await screen.locator("value=/^\\d+$/").tap();
	// FIXME: recorded by coordinates (recorded by coordinates)
	await screen.tapAt({ x: 120, y: 340 });
	// FIXME: recorded by coordinates; the spec API has no long press at a point
	throw new Error("FIXME: long press at a point (recorded by coordinates)");
	// FIXME: recorded without a target; the spec API has no typing without a target field
	throw new Error("FIXME: typing without a target field (recorded without a target)");
	// FIXME: recorded without a target; the spec API has no key press without a target field
	throw new Error("FIXME: key press without a target field (recorded without a target)");
});
